import{_ as r,a as t,b as o,c as s,d as i}from"./chunks/b7c5b8b0d958dab87f06.hVUxgseW.js";import{_ as n,C as l,o as c,c as h,j as e,a as d,E as u,a5 as m}from"./chunks/framework.DNkHA0lr.js";const T=JSON.parse('{"title":"专注力是一种超级力量（如何在信息时代取得成功）","description":"","frontmatter":{"title":"专注力是一种超级力量（如何在信息时代取得成功）","originalTitle":"Focus Is A Superpower (How To Succeed In The Information Age)","date":"2023-07-01","originalUrl":"https://thedankoe.com/letters/focus-is-a-superpower-how-to-succeed-in-the-information-age/","minutes":13,"sourceHash":"b954f71e5d4b30cf6def2593edb9914350d5b128eb29af873591b32b185bce17","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/focus-is-a-superpower-how-to-succeed-in-the-information-age/"}]]},"headers":[],"relativePath":"letters/focus-is-a-superpower-how-to-succeed-in-the-information-age.md","filePath":"letters/focus-is-a-superpower-how-to-succeed-in-the-information-age.md"}'),f={name:"letters/focus-is-a-superpower-how-to-succeed-in-the-information-age.md"};function b(_,p,g,k,q,w){const a=l("ArticleMeta");return c(),h("div",null,[p[0]||(p[0]=e("h1",{id:"专注力是一种超级力量-如何在信息时代取得成功",tabindex:"-1"},[d("专注力是一种超级力量（如何在信息时代取得成功） "),e("a",{class:"header-anchor",href:"#专注力是一种超级力量-如何在信息时代取得成功","aria-label":'Permalink to "专注力是一种超级力量（如何在信息时代取得成功）"'},"​")],-1)),u(a),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/83O-aP6ISyM?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>这就是我们今天在此要讨论的内容。</p><p>这是一个为你自己创造更好生活的简单框架。</p><p>但首先，我们需要了解它的重要性。</p><p>为什么专注工作是一种超级力量？</p><p>幸福是一项技能，而现在比以往任何时候都更容易练习“不幸福”。</p><p>怎么会这样？</p><p>我们生活的世界与我们的祖先不再一样了。</p><p>物质世界当然已经改变了。</p><p>有了更多的建筑。</p><p>我们的作息也不同了。</p><p>环境的改变反映了人类的进步，但除非我们倒退回去，或者创造一个可持续的解决方案，否则这可能对我们的长期健康有害。</p><p>但精神世界呢？那完全是另一回事了。</p><p>随着我们不断建设物质世界，我们的大脑必须适应和进化，以发现和应用新信息。</p><p>我们将这称为创造力，我们神圣的天赋。</p><p>在人类意识出现之前，物质世界就已经存在了。</p><p>当心智层面出现时，它超越并包容了物理和生物层面。</p><p>意思是，物理层面是更广阔生物层面的一部分，而生物层面又是更宏大心智层面的一部分。</p><p><a href="https://www.integralworld.net/reynolds6.html" target="_blank" rel="noreferrer"></a><img src="'+t+'" alt=""></p><p>把旧世界想象成一颗橡子。</p><p>把新世界想象成一棵百年的橡树（它可以活到600到1000岁）。</p><p><img src="'+o+'" alt=""></p><p>它有一个粗壮的树干核心，分出3到6个主要区域，并继续分裂成可能会存活或枯落的树枝，以及成千上万片叶子。每片叶子内部都有一个生态系统。</p><p>当然，你可能需要修剪枝条，以鼓励它朝着正确的方向生长。</p><p>我们可以把这棵橡树看作是对现实的一种通俗简化的描述。</p><p>有无数的枝叶可供探索，但大多数人都被局限在童年时学到的<em>那一个</em>之中。他们通过思想的编程，将自己的潜力限制在无数树枝中的一根上。</p><p>如果你愿意，你可以把那根树枝看作是“母体（The Matrix）”。</p><p>这棵橡树是需要用心智去探索的。</p><p>每一根树枝代表一条信息路径，可以用能量、注意力和意志去探索。</p><p><strong>主要问题在于：</strong></p><p>现代人太容易被吸入平庸、堕落和机械化这种无意识的陷阱中。</p><p>当人们脱离默认路径时，他们会对未知感到恐惧。</p><p>有太多的信息需要探索。</p><p>太多的机会让人不知所措。</p><p>太多的观点会导致焦虑。</p><p>为了找到清晰感，你必须在混乱中奋力拼杀。</p><p>你不能在一遇到困难的苗头时就退缩。</p><p>每一个好念头背后，都有一百个坏念头。</p><p>你构想的成功版本令人振奋，但随之而来的是对失败的担忧：要花多长时间、需要学习哪些技能、以及到达目标的不同职业和商业路径。</p><p>然后，那些糟糕的想法可能会再分裂出另外一百个。</p><p>除非你学会如何梳理自己的思绪。</p><p>从混乱中创造清晰。</p><h2 id="编程-还是被编程" tabindex="-1">编程，还是被编程 <a class="header-anchor" href="#编程-还是被编程" aria-label="Permalink to &quot;编程，还是被编程&quot;">​</a></h2><p>信息时代令人窒息。</p><p>在这个时代，你能做的最重要的事情就是筛选和打造你的数字、精神和物理环境。</p><p><strong>数字环境 –</strong> 让自己沉浸在那些能为你的人生成功“编程”的信息中。</p><p>取关那些对你的未来无益的账号。</p><p>购买能提升你对自己潜力认知的书籍。</p><p>订阅那些教你学校不会教的知识的播客、新闻信和博客。</p><p>无论你转向何处，都要去打造一个让成功成为必然的数字环境。</p><p>为你的大脑编程。</p><p><strong>精神环境</strong> – 把你的大脑当作一个花园。你的思想可以被照料得很美丽，也可以像杂草一样疯长，导致混乱的恶性循环。</p><p>正如阿拉伯人所说：“<em>雨水的本质是一样的，但它让沼泽生出荆棘，让花园绽放鲜花。</em>”</p><p><strong>物理环境</strong> – 满足于安逸的人们形成了定居点。他们互相为彼此平庸的生活辩护，并被设定为相信这是正常的。而未知之地，才是你潜力所在。</p><blockquote><p>“<em>你做出的最重要的决定就是你住在哪里。__它驱动着你的商业机会、人际关系、食物和水源供应、政治、活动以及日常的生活质量。</em>” —— 纳瓦尔（Naval）</p></blockquote><p>你是你所处环境的产物。</p><p>你的思想、情绪和行动（按此顺序）都会受到环境中人与信息的影响。</p><p>思维过程会变成习惯。</p><p>随着时间推移，被编程进你的大脑。</p><p>大多数人在浑浑噩噩地过了40年机械生活后醒来，纳闷时间都去哪儿了。</p><p>别成为他们中的一员。</p><p><strong>人类的行为是以目标为导向的。</strong></p><p>我们所做的一切都与一个目标保持一致。</p><p>每一件事。</p><p>我们做出的每一个决定，都在将我们推向一个有意识或无意识的目标。</p><p>目标早已刻入你的身份中。</p><p>你的身份影响着你对各种情况的看法。</p><p>你的看法影响着你如何看待该情况下的问题。</p><p>你只能根据你目前所处的发展水平来看待各种情况。</p><p>这就是为什么有那么多人充满怨恨、觉得被冒犯和愤怒。</p><p>他们在童年之后就停止了学习和成长。</p><p>当你选择过早的“死亡”时，你就错过了生活的深度。</p><p>对大多数人来说，他们所知道的全部就是“上学、找工作、65岁退休”。</p><p>这就是为什么我如此大力提倡人们通过创作者经济（creator economy）来传播对<a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">新机遇的认知。</a></p><p>大脑是一台模式识别机器。</p><p>由于默认的生活轨迹在你还是个孩子的时候，通过你的成长环境、学校教育以及你周围普通朋友的所作所为，被植入到你的大脑中——你也会随波逐流做同样的事。</p><p>如果你不为成功给大脑编程，它就会被编程走向平庸。</p><h2 id="专注-生活质量" tabindex="-1">专注 = 生活质量 <a class="header-anchor" href="#专注-生活质量" aria-label="Permalink to &quot;专注 = 生活质量&quot;">​</a></h2><p><img src="'+s+'" alt=""></p><blockquote><p>想象一下，有一张电子表格，显示了你在生活中任何特定领域投入了多少注意力。那些影响你与世界及周围人关系的心智、身体、精神和事业。这张表格将是你生活质量的直接指示器。——《专注的艺术》（The Art of Focus）</p></blockquote><p>专注是习惯中的习惯。</p><p>有意识地专注于你的长短期目标，是你为大脑编程以获得成功和日常高质量生活的方式。</p><p>专注是你整个生命存在的根基。</p><p>它是你将觉察力、意识和注意力引导至价值或干扰的方式。</p><p>两者都会导致大脑中多巴胺水平的升高。</p><p>很明显，多巴胺会让你感觉良好。</p><p>干扰会带来“廉价”的多巴胺。</p><p>价值会带来“高昂”的多巴胺。</p><p>我们希望在生活中增加高昂多巴胺源与廉价多巴胺源的比例。</p><p>我们希望提高信噪比，提高重要与无关紧要、有意义与无意义的比例。</p><p>我们从建立一个由自我生成的目标层级系统开始。</p><p>如果你没有有意识的、有意义的目标，你将无法把注意力集中在这些事情上。</p><p>如果你还“不知道”那些目标应该是什么，没关系。</p><p>挑一些听起来有意义的事情。</p><p>只有那样你才能意识到你不想要什么。</p><p>而通过意识到你不想要什么，你就可以把注意力转移到更接近你想要的事物上。</p><p>随着时间的推移，你实现了那些不是别人强加给你的目标，并开辟了你自己的道路。</p><p>如果你对获取高价值技能或将自己变成一家一人企业感兴趣，看看 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 或 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>。</p><p>以下是你该怎么做：</p><h3 id="_1-放大视野以获得全局观" tabindex="-1">1) 放大视野以获得全局观 <a class="header-anchor" href="#_1-放大视野以获得全局观" aria-label="Permalink to &quot;1) 放大视野以获得全局观&quot;">​</a></h3><p>想象你理想的未来。</p><p>你曾经这么做过吗？</p><p>如果有，上一次是什么时候？</p><p>拿出一个笔记本，详细描述它。</p><p>花30分钟写下你认为你想要的东西。</p><p>心智、身体、精神、事业，以及这些东西将如何以有益的方式影响你生活的方方面面。</p><p>将那种生活与你现在的生活做个对比。</p><p>这就是你对未来的愿景。</p><p>一个宏大的、涵盖你其余所有目标的元目标。</p><p>这为你提供了一个视角——或框架——来审视日常生活中的情况。</p><p>你目前正从无意识目标的视角来看待情况。你的注意力被那些有助于实现这些目标的事情所吸引。比如一个工作机会、一个你想发生浅薄肉体关系的人，或者生活中你想解决的其他低意识层次的问题。</p><p>注意：你可能必须解决这些问题才能突破到下一个层次。肤浅的追求并不坏。它们可以作为一个载体，让你接触到深层次的东西。许多人开始去健身房是为了好身材，但坚持下来是因为它成了一种治愈。</p><p>把你的框架当作一个过滤干扰的力场。</p><p>大多数人的力场是外界投射给他们的，这就是为什么他们一生碌碌无为。</p><h3 id="_2-拆解目标以弥合清晰度差距" tabindex="-1">2) 拆解目标以弥合清晰度差距 <a class="header-anchor" href="#_2-拆解目标以弥合清晰度差距" aria-label="Permalink to &quot;2) 拆解目标以弥合清晰度差距&quot;">​</a></h3><p>在你拿出的那个笔记本里，把你生活的每个领域分解成可管理的子目标。</p><p>写下：</p><ul><li>一个10年目标</li><li>一个1年目标</li><li>本月目标</li><li>本周目标</li><li>你今天能做的事</li></ul><p>不要执着于这些目标。</p><p>这是一个产生清晰感的练习。</p><p>你的目标会随着时间推移而演变，这没关系。</p><p>它们可能明天就变了。</p><p>如果你不这么做，你按社会强加给你的目标行事的可能性就会高得多。</p><p>把这个笔记本放在手边。</p><p>把它写得乱七八糟，然后再整理，接着去行动。</p><h3 id="_3-拉近焦距以带着目的行动" tabindex="-1">3) 拉近焦距以带着目的行动 <a class="header-anchor" href="#_3-拉近焦距以带着目的行动" aria-label="Permalink to &quot;3) 拉近焦距以带着目的行动&quot;">​</a></h3><p>把你的框架记在脑海深处。</p><p>记住，这是你正在养成的一个习惯。</p><p>你正试图通过将注意力拉回你认为重要的事情上，来减少生活中的干扰。</p><p>你养成的每一个其他行动，并最终成为习惯，都应该指向你的愿景。</p><p>这就是你如何活出知行合一的境界。</p><p>你能感觉得到。</p><p>问题是，我们该把焦点拉近到什么上？</p><p>我们怎么知道自己每天都在进步？</p><h2 id="一个项目-一个小时-一次只过好一天" tabindex="-1">一个项目，一个小时，一次只过好一天 <a class="header-anchor" href="#一个项目-一个小时-一次只过好一天" aria-label="Permalink to &quot;一个项目，一个小时，一次只过好一天&quot;">​</a></h2><p>现代世界是一张无限的信息网。</p><p>想法、机会、商业模式、情感建议、生产力教条、阴谋论、新闻和八卦，如果你不训练自己的专注力，你就会迷失其中。</p><p>在你目前的人生阶段，你接触到的99%的信息都是干扰。</p><p>我们必须收拢心思，专注于那几件能让我们过上更好生活的事情上。</p><p><em>这因人而异。</em></p><h3 id="一个有意义的项目" tabindex="-1">一个有意义的项目 <a class="header-anchor" href="#一个有意义的项目" aria-label="Permalink to &quot;一个有意义的项目&quot;">​</a></h3><p>从你在笔记本上写下的内容中，<em>把你的目标转化为项目。</em></p><p>你就是那个元项目。</p><p>你就是你毕生的事业。</p><p>你作为一个项目，是由让生活充满乐趣的相互关联的存在层面所组成的。</p><p>心智、身体、精神和金钱（是的，金钱是必需的。它是商业的桥梁。社会的命脉。它是你将想要构建的未来变为现实的手段）。</p><p>在商业领域，这些都是永恒的市场，那里存在着亟待解决、有利可图的问题。因为它们是真实的人们生活中的<em>真实</em>问题。</p><p>当你在这些领域内为自己的问题创造出解决方案时：</p><ul><li>你解锁了开启一个更有意义（也更赚钱）的项目或迈向人生下一阶段的能力。</li><li>你可以将你的解决方案分享给像你一样需要帮助的人——这就是为什么你就是最赚钱的细分领域背后的逻辑。</li><li>你在现实中取得了实实在在的进展。你不会陷入精神自慰和教程地狱的死循环中。</li></ul><p>因此，我们必须把我们的人生当作一个项目，拆解成一个个后续的子项目，以此来攀登个人成功的阶梯。</p><p>你可以把这些项目看作电子游戏里的任务。</p><p>这就是为什么电子游戏很好玩。</p><p>它们让你的心思聚焦在一系列层级分明的目标上。</p><p>你开始掌控你的注意力。</p><p>你带着目标在这个世界上前行。</p><p>人们能从你的举止中察觉到这一点。</p><p>你充满自信地走在路上，因为不再有任何杂念能蒙蔽你最真实的状态。</p><h3 id="一小时的专注工作" tabindex="-1">一小时的专注工作 <a class="header-anchor" href="#一小时的专注工作" aria-label="Permalink to &quot;一小时的专注工作&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>你不需要每天花12个小时来实现你的梦想。</p><p>如果真是那样的话，没人能看到任何形式的成功。</p><p>成年人是有责任的。</p><p>家庭、工作以及要付的账单都需要他们集中精力，直到这些问题被解决。</p><p>对于你的第一个有意义的项目，选择一个能解决你生活中最主要问题的。</p><p>这就是你的使命。</p><p>静下心来面对它，深思熟虑，然后制定一个出击计划。</p><p>你超重了吗？</p><p>你身无分文吗？</p><p>你总是压力山大吗？</p><p>你讨厌你的工作吗？</p><p>你缺乏精力吗？</p><p>到底是什么问题？</p><p>你到底在掩盖什么，好让自己不必去面对成长伴随而来的痛苦？</p><p>如果被解决，哪个问题能为你解锁下一层级的人生乐趣？</p><p>明确之后，你必须将那个目标拆解成可以融入你生活方式的具体行动。</p><p>你的生活必须在根本层面上发生改变。</p><p>你将不得不牺牲你目前正在做的事——因为如果你想要成长，你一开始就不该做你现在正做的事。</p><p>如果你不每天做，它就不是一个习惯。</p><p>如果它不是一个习惯，结果就是暂时的。</p><p>习惯的养成需要你改变一部分自我。</p><p>如果你需要钱，就把你每天的第一个小时投入到关于金钱的学习和行动中。</p><p>如果你想减肥，就把你每天的第一个小时投入到关于健身的学习和行动中。</p><p>如果你想减轻压力，就把你每天的第一个小时投入到关于心理健康的学习和行动中。</p><h3 id="一天一天来" tabindex="-1">一天一天来 <a class="header-anchor" href="#一天一天来" aria-label="Permalink to &quot;一天一天来&quot;">​</a></h3><p>专注力是一种货币。</p><p>当你把它投资于你自己的学习、工作、休息和成功时，结果不会是立竿见影的。</p><p>持之以恒是必需的。</p><p>实际上，收回那句话，持之以恒被高估了。</p><p>坚持不懈和不断迭代才是必需的。</p><p>你必须每天按时出现，带着打造一个能延续到未来的项目的决心。</p><p>你就是这样成为一个自信且有趣的人的。</p><p>当你铁了心要实现你的愿景时，人们会注意到的。</p><p>作为领导者，你会吸引追随者。</p><p>他们为你提供资源，让你建设得更快。</p><p>人们采纳你的观点，他们的生活因此得到改善。</p><p>当然，会有一些人试图把你拉下来，但他们只是极少数。你会学会如何应对并无视他们。</p><p>你如何让持续的行动变得顺理成章？</p><p>通过把那些能撬动杠杆的任务，安排进你一天中高能量的时间段里。</p><p><strong>1) 撬动杠杆的任务</strong></p><blockquote><p>至于方法，可能有一百万种甚至更多，但原则却很少。掌握原则的人能成功地选择自己的方法。而尝试各种方法却无视原则的人，肯定会遇到麻烦。——哈灵顿·埃默森 (Harrington Emerson)</p></blockquote><p>坚持不懈的关键在于势能。</p><p>你需要积累<em>微小</em>的胜利。</p><p>就像打电子游戏一样。</p><p>如果你从未取得任何进展，你为什么还要继续玩下去？那一点都不好玩。</p><p>这就是其他陷阱开始起作用的地方。</p><p>太多人在没有方向或未加学习的情况下就开始工作。</p><p>他们死盯着方法不放，而不是将原则变成习惯。</p><p>从你已知的开始。</p><p>优先建立对全局的理解。</p><p>当你遇到具体问题时，再去学习那些技术细节。</p><p>如果你想减肥，在了解训练和营养的原则之前，就开始读一本关于甲状腺功能减退的书，那是愚蠢的。</p><p>如果你想创业，在了解流量和产品主张的原则之前，就去买一门关于用Facebook广告获客的课程，那是愚蠢的。</p><p>如果你想去约会，在理解社交、亲密或商业关系原则之前，就去学所谓的“搭讪技巧”，那是愚蠢的。</p><p>你会发现原则在生活的多个领域是重叠的。这意味着，你能更快地取得全方位的进步。</p><p>就像你在做生意时也能运用“增肌”和“减脂”策略一样。</p><p>或者在约会中，你需要把有价值的“产品主张”展示在“精准流量”面前。</p><p>开始你那个有意义的项目吧。</p><p>买那些着眼于该主题全貌的书。</p><p>搞清楚你每天必须完成的那些能撬动杠杆的任务。</p><p><strong>2) 高能量时间段</strong></p><p>对大多数人来说，把早上第一件事的时间划分出来用于专注工作是明智之举。</p><p>特别是如果你有工作或家庭。</p><p>你的精力可能看起来不是“最充沛的”，但你每天的精力都是有限的。</p><p>难道你打算在下班后再去筑梦吗？</p><p>我试过了，很难坚持下来。</p><p>难道你打算在家庭琐事塞满你的大脑时再去筑梦吗？</p><p>多半不会。</p><p>放过自己，让事情变得简单点。</p><p>试着早起一个星期。</p><p>熬过那种不适感。</p><p>把它变成习惯。这种困难不会持续太久的。</p><p>慢慢地你会喜欢上它的。</p><p>如果你还年轻，且没担什么责任，同样的道理也适用。</p><p>你想什么时候工作都行，但要认清你生活中的那些干扰因素。</p><p>干扰是主观的。</p><p>我不是说你的朋友和电子游戏不好。</p><p>但相对于你的梦想而言，它们会阻碍你的进步。</p><p>在早上工作。</p><p>搞定你的优先任务。</p><p>轻松地享受这一天剩下的时光吧，因为你已经做完了你该做的事。</p><p>这封信就写到这里。</p><p>祝周末愉快。</p><p>– Dan Koe</p><hr><p><a href="/en/letters/focus-is-a-superpower-how-to-succeed-in-the-information-age">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',246))])}const A=n(f,[["render",b]]);export{T as __pageData,A as default};
